/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { CurvesScreen } from "../../src/curves/CurvesScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { IndicatorsScreen } from "../../src/indicators/IndicatorsScreen.js";
import { LabScreen } from "../../src/lab/LabScreen.js";
import { TitrationLabPreferencesModel } from "../../src/preferences/TitrationLabPreferencesModel.js";
import TitrationLabColors from "../../src/TitrationLabColors.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from titrationLabQueryParameters.
  const simPreferences = new TitrationLabPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new LabScreen({
      showReadingProperty: simPreferences.showReadingProperty,
      name: stringManager.getScreenNames().labStringProperty,
      tandem: Tandem.ROOT.createTandem("labScreen"),
      backgroundColorProperty: TitrationLabColors.backgroundColorProperty,
    }),
    new CurvesScreen({
      name: stringManager.getScreenNames().curvesStringProperty,
      tandem: Tandem.ROOT.createTandem("curvesScreen"),
      backgroundColorProperty: TitrationLabColors.backgroundColorProperty,
    }),
    new IndicatorsScreen({
      name: stringManager.getScreenNames().indicatorsStringProperty,
      tandem: Tandem.ROOT.createTandem("indicatorsScreen"),
      backgroundColorProperty: TitrationLabColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { TitrationLabColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
